export const ERROR_ALERT_SHOW = 'ERROR_ALERT_SHOW'
export const ERROR_ALERT_HIDE = 'ERROR_ALERT_HIDE'
export const SUCCESS_ALERT_SHOW = 'SUCCESS_ALERT_SHOW'
export const SUCCESS_ALERT_HIDE = 'SUCCESS_ALERT_HIDE'
export const INFO_ALERT_SHOW = 'INFO_ALERT_SHOW'
export const INFO_ALERT_HIDE = 'INFO_ALERT_HIDE'


export function handleAlertChange(alertType, alertAction) {
    
    console.log(alertType+'_ALERT_'+alertAction);
    return (dispatch, getState) => {
        dispatch({type: alertType+'_ALERT_'+alertAction})
    }

    
}
